CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, person TEXT, expires REAL);
CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY AUTOINCREMENT, nonce TEXT UNIQUE, author TEXT, recipient TEXT, text TEXT, drawing TEXT, paper TEXT, created REAL, format INTEGER NOT NULL DEFAULT 1, text_size INTEGER NOT NULL DEFAULT 40);
CREATE TABLE IF NOT EXISTS attempts(ip TEXT PRIMARY KEY, count INTEGER, until REAL);
